const sortNumbers = (numbers) => {
  const value_map = {
    'zero': 0,
    'one': 1,
    'two': 2,
    'three': 3,
    'four': 4,
    'five': 5,
    'six': 6,
    'seven': 7,
    'eight': 8,
    'nine': 9
  };

  // Split the input string into an array of words
  const words = numbers.split(' ');

  // Filter out any empty strings from the array
  const nonEmptyWords = words.filter(word => word !== '');

  // Convert each word to its corresponding number using the value_map
  const numberArray = nonEmptyWords.map(word => value_map[word]);

  // Sort the array of numbers
  numberArray.sort((a, b) => a - b);

  // Convert the sorted array back to a string and return it
  return numberArray.join(' ');
}
