const uniqueDigits = (x) => {
  let p = [];
  for (let i = 0; i < x.length; i++) {
    let h = x[i];
    let boo = 1;
    while (h > 0) {
      let r = h % 10;
      if (r % 2 == 0) {
        boo = 0;
        break;
      }
      h = (h - r) / 10;
    }
    if (boo) {
      p.push(x[i]);
      p.push(h);
    }
  }

  // Sort the array based on the second element of each sub-array
  p.sort((a, b) => a[1] - b[1]);

  // Remove duplicates by keeping only the first occurrence of each number
  let result = [];
  for (let i = 0; i < p.length; i++) {
    if (!result.includes(p[i][0])) {
      result.push(p[i][0]);
    }
  }

  return result;
}

