const sortedListSum = (lst) => {
  let p = [];
  for (let i = 0; i < lst.length; i++) {
    if (lst[i].length % 2 == 0) {
      p.push(lst[i]);
    }
  }

  // Sort the array of strings based on their length and lexicographical order
  p.sort((a, b) => {
    if (a.length !== b.length) {
      return a.length - b.length;
    } else {
      return a.localeCompare(b);
    }
  });

  return p;
};

